shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #294057;
    --gold-ink: #e2b878;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif);
    font-size: 18px;
    line-height: 1.82;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    overflow-x: hidden;
    background-color: var(--paper);
    background-image: radial-gradient(rgba(20, 20, 19, 0.03) 1px, transparent 0);
    background-size: 24px 24px;
  }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(228, 223, 211, 0.5);
    z-index: 1001;
  }
  .progress-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.65rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }
  .wsj-monogram {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    border-right: 1px solid var(--line-strong);
    padding-right: 0.75rem;
  }
  .section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 600;
  }
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 999px;
    padding: 2px;
  }
  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 600;
    padding: 0.25rem 0.7rem;
    border-radius: 999px;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Header */
  .hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }
  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 2px;
    background: var(--accent);
  }
  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.18;
    color: var(--ink);
    letter-spacing: -0.015em;
    max-width: 980px;
    margin-bottom: 1.35rem;
  }
  .hero-dek {
    font-family: var(--font-serif);
    font-size: clamp(1.08rem, 1.8vw, 1.32rem);
    line-height: 1.65;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
  }

  /* Dateline & Telemetry Strip */
  .hero-meta-grid {
    display: grid;
    grid-template-columns: 1.2fr 2fr;
    gap: 1.5rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line);
    align-items: center;
  }
  .byline-block {
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }
  .byline-author {
    font-weight: 700;
    color: var(--ink);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    margin-bottom: 0.2rem;
  }
  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.75rem;
  }
  .telemetry-strip {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    background: var(--paper-card);
    border: 1px solid var(--line);
    border-left: 3px solid var(--accent);
    padding: 0.85rem 1.1rem;
  }
  .telemetry-item {
    display: flex;
    flex-direction: column;
    gap: 0.15rem;
  }
  .telemetry-label {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
  }
  .telemetry-value {
    font-family: var(--font-mono);
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--ink);
  }
  .telemetry-sub {
    font-family: var(--font-sans);
    font-size: 0.72rem;
    color: var(--accent);
    font-weight: 500;
  }

  /* Layout Containers */
  .editorial-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 0 1.5rem;
  }

  .chapter-banner {
    margin: 3.2rem 0 1.8rem;
    display: flex;
    align-items: baseline;
    gap: 1rem;
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 0.65rem;
  }
  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }
  .chapter-title {
    font-family: var(--font-display);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  /* Asymmetric Editorial Grid */
  .asymmetric-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 380px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  .prose-col {
    min-width: 0;
  }

  .prose-p {
    margin-bottom: 1.45rem;
    color: var(--body);
    font-size: 1.04rem;
    line-height: 1.86;
  }

  /* Lead paragraph styling (no ::first-letter on Chinese) */
  .prose-p.lead-p {
    font-size: 1.15rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 500;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, var(--accent-soft) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
    border-bottom: 1px solid rgba(184, 93, 25, 0.45);
  }

  /* Side Rail Components */
  .side-rail {
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
    position: sticky;
    top: 4.5rem;
  }

  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
    position: relative;
  }
  .dossier-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: var(--ink);
  }
  .dossier-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.5rem;
    font-weight: 700;
  }
  .dossier-title {
    font-family: var(--font-display);
    font-size: 1.12rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.35;
  }
  .dossier-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.7rem;
    font-family: var(--font-sans);
    font-size: 0.84rem;
    line-height: 1.55;
  }
  .dossier-list li {
    padding-top: 0.65rem;
    border-top: 1px dashed var(--line-strong);
    display: flex;
    justify-content: space-between;
    gap: 0.75rem;
  }
  .dossier-list li:first-child {
    border-top: none;
    padding-top: 0;
  }
  .dossier-key {
    color: var(--muted);
    font-weight: 500;
    flex-shrink: 0;
  }
  .dossier-val {
    color: var(--ink);
    font-weight: 600;
    text-align: right;
  }

  /* Derived Pull Quote */
  .pull-quote {
    background: var(--paper);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.35rem 0.25rem;
    margin: 0.5rem 0;
  }
  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.15rem;
    line-height: 1.55;
    color: var(--ink);
    margin-bottom: 0.75rem;
  }
  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  /* Derived Metric Card */
  .metric-card {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.35rem;
    border-left: 4px solid var(--accent);
  }
  .metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 2.3rem;
    font-weight: 700;
    color: var(--gold-ink);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }
  .metric-card .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: #ffffff;
    margin-bottom: 0.45rem;
  }
  .metric-card .metric-note {
    font-family: var(--font-serif);
    font-size: 0.8rem;
    line-height: 1.5;
    color: #c5ced6;
  }

  /* Primary Split Blockquote inside Narrative Flow */
  .narrative-quote-box {
    margin: 1.85rem 0;
    padding: 1.4rem 1.6rem;
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    font-family: var(--font-display);
    font-size: 1.22rem;
    line-height: 1.58;
    color: var(--ink);
  }

  /* SVG Exhibit Card */
  .exhibit-panel {
    margin: 2.6rem 0;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.65rem;
  }
  .exhibit-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 1rem;
    margin-bottom: 1.1rem;
    border-bottom: 1px solid var(--line);
    padding-bottom: 0.8rem;
  }
  .exhibit-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.25rem;
  }
  .exhibit-title {
    font-family: var(--font-display);
    font-size: 1.25rem;
    color: var(--ink);
    font-weight: 700;
  }
  .exhibit-sub {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    color: var(--muted);
    margin-top: 0.2rem;
  }
  .exhibit-footnote {
    margin-top: 0.85rem;
    padding-top: 0.65rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  /* Dark Navy Full-Bleed Breakout for Fed Policy Tension */
  .navy-breakout {
    background: var(--navy-bg);
    color: var(--paper);
    margin: 3.5rem 0;
    padding: 3.2rem 1.5rem;
    border-top: 3px solid var(--accent);
    border-bottom: 3px solid var(--accent);
  }
  .navy-inner {
    max-width: 1180px;
    margin: 0 auto;
  }
  .navy-header {
    margin-bottom: 2rem;
    border-bottom: 1px solid var(--navy-line);
    padding-bottom: 1rem;
  }
  .navy-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--gold-ink);
    margin-bottom: 0.4rem;
  }
  .navy-title {
    font-family: var(--font-display);
    font-size: clamp(1.5rem, 2.6vw, 2.1rem);
    color: #ffffff;
    font-weight: 700;
  }

  /* Policy Comparison Matrix */
  .policy-matrix {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
    margin-top: 1.75rem;
  }
  .matrix-col {
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 1.35rem;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
  }
  .matrix-col.highlight-col {
    border-top: 3px solid var(--gold-ink);
  }
  .matrix-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--gold-ink);
  }
  .matrix-actor {
    font-family: var(--font-display);
    font-size: 1.18rem;
    color: #fff;
    font-weight: 700;
  }
  .matrix-desc {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    line-height: 1.6;
    color: #d2dbe4;
  }

  /* Final Governance Duel Box */
  .duel-panel {
    margin: 2.2rem 0;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.5rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
  }
  .duel-side {
    padding: 0.5rem;
  }
  .duel-side:first-child {
    border-right: 1px dashed var(--line-strong);
    padding-right: 1.5rem;
  }
  .duel-role {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 0.3rem;
  }
  .duel-name {
    font-family: var(--font-display);
    font-size: 1.15rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.55rem;
  }
  .duel-philosophy {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    line-height: 1.6;
    color: var(--body);
  }

  /* Footer */
  .ed-footer {
    max-width: 1180px;
    margin: 4rem auto 0;
    padding: 2rem 1.5rem 3.5rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .hero-meta-grid,
    .asymmetric-grid,
    .policy-matrix,
    .duel-panel {
      grid-template-columns: 1fr;
    }
    .side-rail {
      position: static;
      margin-top: 1rem;
    }
    .duel-side:first-child {
      border-right: none;
      border-bottom: 1px dashed var(--line-strong);
      padding-right: 0.5rem;
      padding-bottom: 1.25rem;
    }
  }

  @media (max-width: 600px) {
    html {
      font-size: 16.5px;
    }
    .masthead {
      padding: 0.55rem 1rem;
    }
    .hero {
      padding: 2.2rem 1rem 1.8rem;
    }
    .editorial-container {
      padding: 0 1rem;
    }
    .telemetry-strip {
      grid-template-columns: 1fr;
      gap: 0.75rem;
    }
    .exhibit-panel {
      padding: 1.1rem;
    }
  }
